// v377 (Ravi's approved round-3 email design): Ybex's own creator illustrations in a purple duotone, made from the
// Diwali design files. Served as PNG by GET /api/email-art/<name>.png so emails can show them (mail apps block
// data: images). One file instead of five, to stay under the 1,000-file limit.
import express from "express";

export const EMAIL_ART: Record<string, string> = {
  group: "",
  phone: "",
  camera: "",
  laptop: "",
  duo: "",
};

export const EMAIL_ART_NAMES = Object.keys(EMAIL_ART);

export function setupEmailArtRoutes(router: express.Router) {
  router.get("/email-art/:name", (req, res) => {
    const name = String(req.params.name || "").replace(/\.png$/i, "");
    const b64 = EMAIL_ART[name];
    if (!b64) return res.status(404).end();
    res.set("Content-Type", "image/png");
    res.set("Cache-Control", "public, max-age=2592000, immutable");
    return res.send(Buffer.from(b64, "base64"));
  });
}
